SELECT md.chembl_id, md.pref_name, cs.canonical_smiles, md.max_phase, dm.mechanism_of_action, dm.action_type, td.chembl_id AS target_chembl_id, td.pref_name AS target_name FROM molecule_dictionary md JOIN drug_mechanism dm ON md.molregno = dm.molregno JOIN target_dictionary td ON dm.tid = td.tid JOIN compound_structures cs ON md.molregno = cs.molregno WHERE md.max_phase = 4 AND dm.action_type = 'BLOCKER' ORDER BY md.chembl_id ASC, md.pref_name ASC, cs.canonical_smiles ASC, md.max_phase ASC, dm.mechanism_of_action ASC, dm.action_type ASC, target_chembl_id ASC, target_name ASC
